 plan=load('deck-plan.json');plan.update(project=data['title'],communication_job=job,design_direction={'name':design['name'],'communication_mode':'hybrid','character':design['direction']['character'],'visual_cluster':'community-instruction','grid':'13.333x7.5 inch, 0.6 inch margins','type':'Yu Gothic, 35pt titles / 20pt body','palette':'navy, paper, terracotta accent','media':'native editable forms and flow','topology_rhythm':'stage-frame-spine-split-matrix-stage','reference_quality_floor':'Readable concrete examples and distinct page relationships.'})
