 profile=load('capability-profile.json');providers={'image_understanding':'Agent visual review','code_execution':'Python and Node local runtime','filesystem':'Local workspace','native_pptx_authoring':'python-pptx 1.0.2','web_slide_authoring':'Original PradaSlides presenter','slide_rendering':'Microsoft PowerPoint 16.0','pptx_roundtrip':'PowerPoint COM','image_generation':'Available image tool; deliberately unused'}
